def gen(rng):
    names = ['a', 'b', 'home', 'usr', 'x1', '_t', '...', '.hid', 'a.b', '..a', 'z9']
    def rnd(segs, p_up, p_dot, p_empty):
        out = ['']
        for _ in range(segs):
            r = rng.random()
            if r < p_up:
                out.append('..')
            elif r < p_up + p_dot:
                out.append('.')
            elif r < p_up + p_dot + p_empty:
                out.append('')
            else:
                out.append(rng.choice(names))
        if rng.random() < 0.4:
            out.append('')
        s = '/'.join(out)
        if not s.startswith('/'):
            s = '/' + s
        return s
    tests = [
        '/home//user/./docs/../photos/', '/../../a/b/../../..', '/x/.../y/.hidden/', '/', '//', '/.', '/..', '/...',
        '/a/', '/a/./b/../../c/', '/a//b////c/d//././/..', '/../', '/..hidden', '/a/b/c/../../../..', '/./././.', '/.a/..b/c.',
    ]
    for segs in (2, 3, 4, 6, 8, 12, 20, 30):
        for _ in range(3):
            tests.append(rnd(segs, 0.3, 0.15, 0.1))
        tests.append(rnd(segs, 0.6, 0.1, 0.05))
        tests.append(rnd(segs, 0.05, 0.05, 0.02))
    # max-size tests
    k = 16000
    tests.append('/' + '/'.join(['ab'] * k) + '/' + '/'.join(['..'] * (k - 5)) + '/')
    tests.append('/' + '/'.join(['..', '.'] * 19000))
    parts = ['']
    while sum(len(p) + 1 for p in parts) < 99900:
        r = rng.random()
        parts.append('..' if r < 0.35 else '.' if r < 0.45 else '' if r < 0.55 else ''.join(rng.choice('abc.') for _ in range(rng.randint(1, 6))))
    s = '/'.join(parts)
    tests.append(s[:100000] if s.startswith('/') else '/' + s[:99999])
    tests.append('/' + '/'.join(['.' * 3] * 24000))
    for t in tests:
        assert 1 <= len(t) <= 100000 and t[0] == '/'
    return tests
